Qual a complexidade deste algoritmo de transposição de matriz?

void transpor(int M[N][N], int n) {
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int temp = M[i][j];
            M[i][j] = M[j][i];
            M[j][i] = temp;
        }
    }
}

Qual a complexidade deste código?

struct No inverter_lista(struct No *head) {
    struct No *prev = NULL, *curr = head, *next = NULL;
    while (curr != NULL) {
        next = curr->prox;
        curr->prox = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

