Determine a complexidade da busca binária iterativa:

int busca_binaria(int v[], int n, int elem) {
    int ini = 0, fim = n - 1;
    while (ini <= fim) {
        int meio = ini + (fim - ini) / 2;
        if (v[meio] == elem) return meio;
        if (v[meio] < elem) ini = meio + 1;
        else fim = meio - 1;
    }
    return -1;
}

